import heapq  # a binary heap is the standard tool for "current maximum" queries

class AuctionSystem:
    def __init__(self):
        # Current bid amount for each (userId, itemId) pair
        self.bids = {}
        # Per item: max-heap of (-amount, -userId), possibly containing stale entries
        self.heaps = {}

    def addBid(self, userId, itemId, bidAmount):
        # Record the current amount (replaces any previous bid by this user)
        self.bids[(userId, itemId)] = bidAmount
        if itemId not in self.heaps:
            self.heaps[itemId] = []
        # Negate both fields: highest amount first, then highest userId
        heapq.heappush(self.heaps[itemId], (-bidAmount, -userId))

    def updateBid(self, userId, itemId, newAmount):
        # Same effect as adding: the old heap entry becomes stale
        self.addBid(userId, itemId, newAmount)

    def removeBid(self, userId, itemId):
        # Lazy deletion: heap entries for this bid will be skipped later
        del self.bids[(userId, itemId)]

    def getHighestBidder(self, itemId):
        heap = self.heaps.get(itemId)
        if not heap:
            return -1
        # Discard stale tops until the top matches a live bid
        while heap:
            neg_amount, neg_user = heap[0]
            if self.bids.get((-neg_user, itemId)) == -neg_amount:
                return -neg_user
            heapq.heappop(heap)
        # Every entry was stale: no active bids remain
        return -1
